  var BJ_V = {'অ':'A','আ':'Av','ই':'B','ঈ':'C','উ':'D','ঊ':'E','ঋ':'F','এ':'G','ঐ':'H','ও':'I','ঔ':'J'};
  var BJ_M = {'ং':'s','ঃ':'t','ঁ':'u'};
  var BJ_D = {'০':'0','১':'1','২':'2','৩':'3','৪':'4','৫':'5','৬':'6','৭':'7','৮':'8','৯':'9','।':'|'};
  var BJ_PRE = {'ি':'w','ে':'‡','ৈ':'‰'}, BJ_POST = {'া':'v','ী':'x','ু':'y','ূ':'z','ৃ':'„'};
  var BJ_PHALA = {'য':'¨','র':'Ö','ব':'^','ম':'§','ল':'¬','ন':'¥','ভ':'¢'}, BJ_HALF = {'ন':'›','স':'¯','ম':'¤'}, BJ_RA2 = {'ট':1,'ড':1,'ঢ':1,'ঠ':1,'\u09dc':1};
  var BJ_CONJ = {"ক্ক": "°", "ক্ট": "±", "ক্ষ্ণ": "²", "ক্ত": "³", "ক্ম": "´", "ক্র": "µ", "ক্ষ": "¶", "ক্ষ্ম": "·", "গ্ন": "¹", "গ্দ": "º", "গ্ধ": "»", "ঙ্ক": "¼", "ঙ্গ": "½", "জ্জ": "¾", "জ্ঝ": "À", "জ্ঞ": "Á", "ঞ্চ": "Â", "ঞ্ছ": "Ã", "ঞ্জ": "Ä", "ঞ্ঝ": "Å", "ট্ট": "Æ", "ড্ড": "Ç", "ণ্ট": "È", "ণ্ঠ": "É", "ণ্ড": "Ê", "ত্ত": "Ë", "ত্থ": "Ì", "ত্র": "Î", "দ্দ": "Ï", "দ্ধ": "×", "দ্ব": "Ø", "দ্ম": "Ù", "ন্ড": "Û", "ন্ধ": "Ü", "ন্স": "Ý", "প্ট": "Þ", "প্ত": "ß", "প্প": "à", "প্স": "á", "ব্জ": "â", "ব্দ": "ã", "ব্ধ": "ä", "ভ্র": "å", "ম্ফ": "ç", "ল্ক": "é", "ল্গ": "ê", "ল্ট": "ë", "ল্ড": "ì", "ল্প": "í", "ল্ফ": "î", "শ্চ": "ð", "শ্ছ": "ñ", "ষ্ণ": "ò", "ষ্ট": "ó", "ষ্ঠ": "ô", "ষ্ফ": "õ", "স্ট": "÷", "স্ফ": "ù", "ড্র": "Wª", "ট্র": "Uª", "ন্ম": "›g", "ন্ন": "›b", "ম্ম": "¤g", "ম্ন": "¤b", "ম্ল": "¤j", "ন্ব": "›e", "ম্ব": "¤^", "স্ক": "¯‹", "স্ব": "¯^", "স্ত": "¯Í", "স্থ": "¯’", "ন্ত": "šÍ", "চ্চ": "”P", "ম্ভ": "¤¢"};
  function toBijoy(s){
    s = String(s == null ? '' : s);
    if(!/[\u0980-\u09FF]/.test(s)) return s;
    s = s.replace(/[\u200c\u200d]/g, '').replace(/\u09a1\u09bc/g, '\u09dc').replace(/\u09a2\u09bc/g, '\u09dd').replace(/\u09af\u09bc/g, '\u09df');
    var H = '\u09cd', out = '', i = 0, n = s.length;
    function clus(c){
      var o = '', k = 0, L, key, ch, pv;
      while(k < c.length){
        var hit = false;
        for(L = Math.min(4, c.length - k); L >= 2 && !hit; L--){ key = c.slice(k, k + L).join(H); if(BJ_CONJ[key]){ o += BJ_CONJ[key]; k += L; hit = true; } }
        if(hit) continue;
        if(k === 0){
          if(c.length > 1 && BJ_HALF[c[0]] && !BJ_PHALA[c[1]]){ o += BJ_HALF[c[0]] + clus(c.slice(1)); return o; }
          o += BJ_C[c[0]]; k++;
        } else {
          ch = c[k]; pv = c[k - 1];
          if(ch === 'র' && BJ_RA2[pv]) o += 'ª';
          else if(BJ_PHALA[ch]) o += BJ_PHALA[ch];
          else o += '&' + BJ_C[ch];
          k++;
        }
      }
      return o;
    }
    while(i < n){
      var ch = s[i];
      if(BJ_V[ch]){ out += BJ_V[ch]; i++; continue; }
      if(BJ_D[ch]){ out += BJ_D[ch]; i++; continue; }
      if(BJ_M[ch]){ out += BJ_M[ch]; i++; continue; }
      if(BJ_C[ch]){
        var ref = false;
        if(ch === 'র' && s[i + 1] === H && BJ_C[s[i + 2]]){ ref = true; i += 2; ch = s[i]; }
        var cons = [ch]; i++;
        while(i + 1 < n && s[i] === H && BJ_C[s[i + 1]]){ cons.push(s[i + 1]); i += 2; }
        var pre = '', post = '';
        while(i < n && (BJ_PRE[s[i]] || BJ_POST[s[i]] || s[i] === 'ো' || s[i] === 'ৌ')){
          var k2 = s[i];
          if(BJ_PRE[k2]) pre += BJ_PRE[k2];
          else if(k2 === 'ো'){ pre += '‡'; post += 'v'; }
          else if(k2 === 'ৌ'){ pre += '‡'; post += 'Š'; }
          else post += BJ_POST[k2];
          i++;
        }
        out += pre + clus(cons) + (ref ? '©' : '') + post;
        continue;
      }
      out += ch; i++;
    }
    return out;
  }

  function unesc(t){ return String(t).replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&'); }
  /* html (text + <b>) -> the same html with every Bangla text run turned into Bijoy ANSI (tags untouched, result re-escaped) */
  function bjHtml(h){
    return String(h == null ? '' : h).replace(/(<\/?b>)|([^<]+)/g, function(m, tag, txt){ return tag ? tag : esc(toBijoy(unesc(txt))); });
  }

